// Travel Request DOCX generator — uses JSZip to reconstruct the OOXML template
// Template derived from TTSD_CL_Travel_Request_Example.docx (field values replaced with {{TOKENS}})

(function () {
  "use strict";

  // Base64-encoded DOCX template (OOXML ZIP with placeholder tokens in word/document.xml)
  var TMPL_B64 = "";

  // Map a travel request record to a flat token→value object
  function buildTokenMap(req) {
    var ef = req.engineeringForm || {};
    var mode = String(req.formMode || "Standard");

    // Determine field values based on form mode
    var travelerName = ef.travelerName || req.travelerName || req.submitterName || "";
    var phone        = ef.phoneNumber || req.phoneNumber || "";
    var purpose      = ef.purposeOfTdy || req.purposeOfTDY || req.purpose || "";
    var tdyStart     = ef.tdyStartDate || req.tdyStartDate || req.startDate || "";
    var tdyReturn    = ef.tdyReturnDate || req.tdyReturnDate || req.returnDate || "";
    var tdyLocation  = ef.tdyLocation || req.tdyLocation || req.destination || "";
    var onBase       = String(ef.tdyLocationOnBase || req.tdyLocationOnBase || "No");
    var numDays      = String(ef.numberOfDays || req.numberOfDays || "");
    var dateRequest  = ef.dateOfRequest || req.dateOfRequest || req.createdAt || "";
    var flying       = String(ef.flying || req.flying || "No");
    var seatPref     = ef.seatPreference || req.seatPreference || "";
    var flightFrom   = ef.flightFrom || req.flightFrom || "";
    var flightTo     = ef.flightTo || req.flightTo || "";
    var returnFlight = ef.returnFlightFrom || req.returnFlightFrom || "";
    var airportXport = String(ef.transportationToFromAirport || req.transportationToFromAirport || "").toLowerCase();
    var airportUpg   = ef.airportRentalUpgradeJustification || req.airportRentalUpgradeJustification || "";
    var airportVeh   = ef.airportRentalVehicleType || req.airportRentalVehicleType || "";
    var tdyXport     = String(ef.transportationAtTDY || req.transportationAtTDY || "").toLowerCase().replace("public transportation", "public");
    var tdyUpg       = ef.tdyRentalUpgradeJustification || req.tdyRentalUpgradeJustification || "";
    var tdyVeh       = ef.tdyRentalVehicleType || req.tdyRentalVehicleType || "";
    var comments     = ef.comments || req.comments || "";
    var travelCo     = ef.travelCo || req.chargeObject || req.travelCO || "";
    var bfm          = ef.bfm || req.bfm || "";
    var addlTravelers = [].concat(ef.additionalTravelers || req.additionalTravelers || []).slice(0, 5);
    var lodgings     = [].concat(ef.lodging || req.lodging || []).slice(0, 3);

    function cb(condition) { return condition ? "☒ " : "☐ "; }
    function safe(v) { return String(v == null ? "" : v) || " "; }

    var map = {
      DATE_REQUEST:    safe(dateRequest),
      TRAVELER_NAME:   safe(travelerName),
      PHONE:           safe(phone),
      TDY_LOCATION:    safe(tdyLocation),
      CB_ONBASE_YES:   cb(onBase.toLowerCase() === "yes"),
      CB_ONBASE_NO:    cb(onBase.toLowerCase() !== "yes"),
      NUMBER_DAYS:     safe(numDays),
      TDY_START:       safe(tdyStart),
      TDY_RETURN:      safe(tdyReturn),
      PURPOSE:         safe(purpose),
      CB_FLYING_YES:   cb(flying.toLowerCase() === "yes"),
      CB_FLYING_NO:    cb(flying.toLowerCase() !== "yes"),
      SEAT_PREF:       safe(seatPref) || " ",
      FLIGHT_FROM:     safe(flightFrom) || " ",
      FLIGHT_TO:       safe(flightTo) || " ",
      RETURN_FLIGHT:   safe(returnFlight) || " ",
      CB_AIRPORT_POV:    cb(airportXport === "pov"),
      CB_AIRPORT_RENTAL: cb(airportXport === "rental"),
      CB_AIRPORT_PASS:   cb(airportXport === "passenger"),
      AIRPORT_UPGRADE: safe(airportUpg) || " ",
      AIRPORT_VEHICLE: safe(airportVeh) || " ",
      CB_TDY_RENTAL:   cb(tdyXport === "rental"),
      CB_TDY_PASS:     cb(tdyXport === "passenger"),
      CB_TDY_PUBLIC:   cb(tdyXport === "public"),
      TDY_UPGRADE:     safe(tdyUpg) || " ",
      TDY_VEHICLE:     safe(tdyVeh) || " ",
      COMMENTS:        safe(comments) || " ",
      TRAVEL_CO:       safe(travelCo) || " ",
      BFM:             safe(bfm) || " ",
    };

    // Additional travelers (rows 1-5)
    for (var r = 1; r <= 5; r++) {
      var t = addlTravelers[r - 1];
      map["TRAVELER_" + r + "_NAME"]  = t ? safe(t.name || t.travelerName) : " ";
      map["TRAVELER_" + r + "_NOTES"] = t ? safe(t.transportationNotes || t.notes) : " ";
    }

    // Lodging rows 1-3
    for (var l = 1; l <= 3; l++) {
      var lg = lodgings[l - 1];
      map["LODGING_" + l + "_LOCATION"] = lg ? safe(lg.location) : " ";
      map["LODGING_" + l + "_CHECKIN"]  = lg ? safe(lg.checkInDate || lg.checkin) : " ";
      map["LODGING_" + l + "_CHECKOUT"] = lg ? safe(lg.checkOutDate || lg.checkout) : " ";
      map["LODGING_" + l + "_OPTION1"]  = lg ? safe(lg.option1) : " ";
      map["LODGING_" + l + "_OPTION2"]  = lg ? safe(lg.option2) : " ";
    }

    return map;
  }

  // Replace all {{TOKEN}} placeholders in the document XML
  function fillTemplate(xml, map) {
    return xml.replace(/\{\{([A-Z0-9_]+)\}\}/g, function (_, key) {
      return Object.prototype.hasOwnProperty.call(map, key) ? map[key] : "";
    });
  }

  // Base64 → Uint8Array (works in all modern browsers)
  function b64ToUint8Array(b64) {
    var binary = atob(b64);
    var bytes = new Uint8Array(binary.length);
    for (var i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  /**
   * createTravelDocxBlob(request) → Promise<Blob>
   * Fills the OOXML template with data from the travel request and returns a DOCX Blob.
   */
  function createTravelDocxBlob(request) {
    if (typeof JSZip === "undefined") {
      return Promise.reject(new Error("JSZip not loaded — cannot generate DOCX."));
    }
    var tokenMap = buildTokenMap(request);
    return JSZip.loadAsync(b64ToUint8Array(TMPL_B64))
      .then(function (zip) {
        return zip.file("word/document.xml").async("string");
      })
      .then(function (docXml) {
        var filled = fillTemplate(docXml, tokenMap);
        return JSZip.loadAsync(b64ToUint8Array(TMPL_B64)).then(function (zip) {
          zip.file("word/document.xml", filled);
          return zip.generateAsync({
            type: "blob",
            mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            compression: "DEFLATE",
            compressionOptions: { level: 6 }
          });
        });
      });
  }

  // Expose globally so travel.js can call it
  window.createTravelDocxBlob = createTravelDocxBlob;
}());
